sparql:
SELECT ?airport ?name WHERE {
  ?airport a <http://www.semanticweb.org/ontologies/airport_ontology#Airport> .
  ?airport <http://www.semanticweb.org/ontologies/airport_ontology#airportName> ?name .
  ?airport <http://www.semanticweb.org/ontologies/airport_ontology#locatedInCountry> ?country .
  ?country <http://www.semanticweb.org/ontologies/airport_ontology#countryName> "Germany" .
} ORDER BY ?name LIMIT 10
